draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();

  // searching lines
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 50 + 20*Math.sin(t), H/2 + 50 + 20*Math.cos(t));
  ctx.stroke();

  // question mark
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.sin(t), H/2 + 50 + 20*Math.cos(t), 10, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20*Math.sin(t), H/2 + 60 + 20*Math.cos(t));
  ctx.lineTo(W/2 + 50 + 20*Math.sin(t), H/2 + 80 + 20*Math.cos(t));
  ctx.stroke();

  // suffering lines
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 50 - 20*Math.sin(t), H/2 + 50 - 20*Math.cos(t));
  ctx.stroke();

  // purpose arc
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50, 30, 0, 2*Math.PI);
  ctx.stroke();

  ctx.restore();
}
